      "layout": "standardStudy",
      "translation": "fürdik • fürdőzik",
      "explanation": [
        "A lényeg: a baden jelentése kádban fürdik, vagy kedvtelésből fürdik a vízben: Im See baden (fürdik a tóban), in der Wanne baden (fürdik a kádban). Alakjai: er badet, badete, hat gebadet.",
        "Szabályos (gyenge) ige, gyakran a gehen igével áll: baden gehen (fürödni megy). Tárggyal azt jelenti, hogy fürdet: das Baby baden (megfürdeti a babát).",
        "Ha valaki mozgásként, sportként úszik (távot tesz meg), az schwimmen, nem baden."
      ],
      "examples": [
        {
          "de": "Im Sommer baden wir im See.",
          "lv": "Nyáron a tóban fürdünk."
        },
        {
          "de": "Abends bade ich gern in der Wanne.",
          "lv": "Esténként szívesen fürdöm a kádban."
        },
        {
          "de": "Sie badet das Baby.",
          "lv": "Megfürdeti a babát."
        },
        {
          "de": "Wollen wir morgen baden gehen?",
          "lv": "Menjünk holnap fürödni?"
        },
        {
          "de": "Hier darf man nicht baden.",
          "lv": "Itt tilos fürödni."
        }
      ],
      "comparison": [
        {
          "word": "schwimmen",
          "meaning": "úszik",
          "example": "Er schwimmt jeden Tag im Pool. – Minden nap úszik a medencében."
        },
        {
          "word": "duschen",
          "meaning": "zuhanyozik",
          "example": "Ich dusche jeden Morgen. – Minden reggel zuhanyozom."
        },
        {
          "word": "sich waschen",
          "meaning": "mosakszik",
          "example": "Ich wasche mich schnell. – Gyorsan megmosakszom."
        }
      ],
      "tip": [
        "Baden gehen = fürödni megy. Próbáld ki a kifejezést nyáron!",
        "Hasonlítsd össze a schwimmen és a duschen igével — nem szinonimák."
      ],
      "important": [
        "A baden nem a sportszerű úszást jelenti — arra a schwimmen való.",
        "Zuhanyozni németül duschen, nem baden."
      ],
