        "Más esetekben a semlegesnem alakja dem (Dativ, részes eset) és des (Genitiv, birtokos eset); többes számban mindhárom nemben die.",
        "A das mutató névmás (Das ist mein Bruder — ez a fivérem) és vonatkozó névmás is. Ne keverd a dass (hogy) kötőszóval: azt két s-sel írjuk, és mellékmondatot vezet be."
