        "Hímnemben és semlegesnemben ein, nőnemben eine. Akkusativban (tárgyeset) a hímnem alakja einen: Ich habe einen Bruder. Dativban (részes eset): einem (hím- és semlegesnem), einer (nőnem). A határozatlan névelőnek nincs többes száma; tagadásban a kein áll.",
        "Az ein számnév is, jelentése 'egy': Ich habe nur ein Kind. Ilyenkor hangsúlyosan ejtjük (ahogy a magyar 'egy' is lehet névelő és számnév)."
