        "Alakjai: du fährst, er fährt (a → ä), fuhr, ist gefahren. Ha nincs tárgy, a Perfekt sein-nel képződik: Ich bin nach Wien gefahren. Ha van Akkusativ (tárgyeset) tárgy (a vezetett jármű), haben-nel: Ich habe das Auto gefahren.",
        "Az irányt (hová?) a nach (város, ország), a zu (személy, hely) vagy az in + Akkusativ fejezi ki; a közlekedési eszközt a mit + Dativ (részes eset)."
