        "A német ugyanúgy megkülönbözteti a két testrészt, mint a magyar a kezet és a kart: a Hand a csuklótól lefelé tartó rész, tenyérrel és ujjakkal; a vállból induló egész végtag der Arm, vagyis kar.",
