        "Alakjai rendhagyók: ich weiß, du weißt, er/sie/es weiß, wir wissen; múlt idő wusste, Perfekt hat gewusst. Gyakran áll dass-mellékmondattal vagy kérdőszóval: Ich weiß, dass… / Weißt du, wo…?",
