        "Alakjai: ich kann, du kannst, er/sie/es kann, wir können, ihr könnt, sie können; múlt idő konnte, Perfekt hat gekonnt. A második ige főnévi igenévként a mondat végén áll: Ich kann heute nicht kommen.",
