        "Akinek valami kerül, az Akkusativban (tárgyeset) áll: Das kostet mich zehn Euro. Átvitt értelemben a kosten időt vagy fáradságot is igényelhet: Das kostet viel Zeit (sok időt vesz igénybe)."
