        "Lényeg: a machen nagyon gyakori ige, jelentése „csinál” és „készít”: Was machst du? (Mit csinálsz?), Wir machen Pizza (pizzát készítünk), Ich mache Hausaufgaben (a házi feladatomat csinálom).",
        "Alakok: macht, machte, hat gemacht. Akkusativval (tárgyeset): etwas machen. Sok kifejezésben ez adja az igét: Spaß machen (jó móka, szórakoztató), eine Pause machen (szünetet tart), Sport machen (sportol), Urlaub machen (szabadságra megy).",
        "Számlánál a machen jelentése „összesen ennyi”: Das macht zehn Euro — ez összesen tíz euró."
