      "explanation": [
        "Lényeg: a schon határozószó, jelentése „már” — azt jelzi, hogy valami korábban vagy hamarabb történt, mint várták: Ich bin schon zu Hause. Hast du schon gegessen?",
        "Helyét tekintve a schon általában az ige után vagy a kiemelt szó előtt áll. Beszélt nyelvben a schon megerősítő módosítószó is lehet: Das ist schon gut (ez azért jó), Es wird schon gehen (majd csak lesz valahogy).",
        "Ellentéte: noch nicht — még nem."
      ],
      "examples": [
        {
          "de": "Ich bin schon zu Hause.",
          "lv": "Már otthon vagyok."
        },
        {
          "de": "Hast du schon gegessen?",
          "lv": "Ettél már?"
        },
        {
          "de": "Es ist schon spät.",
          "lv": "Már késő van."
        },
        {
          "de": "Wie lange wohnst du schon hier?",
          "lv": "Mióta laksz már itt?"
        },
        {
          "de": "Es wird schon gehen.",
          "lv": "Majd csak lesz valahogy."
        }
      ],
      "comparison": [
        {
          "word": "noch",
          "meaning": "még",
          "example": "Ich bin noch nicht fertig. – Még nem vagyok kész."
        },
        {
          "word": "erst",
          "meaning": "még csak (időben)",
          "example": "Es ist erst acht Uhr. – Még csak nyolc óra van."
        },
        {
          "word": "bereits",
          "meaning": "már (választékos)",
          "example": "Er ist bereits abgereist. – Már elutazott."
        }
      ],
      "tip": [
        "Noch nicht = még nem; schon = már: Hast du schon gegessen? – Nein, noch nicht.",
        "Ha a kérdésben schon van, gyakran „igen” választ várnak."
      ],
      "important": [
        "A schon nem jelenti azt, hogy „szép”; a szép jelentésű szó a schön — írásban és kiejtésben is különböznek.",
        "Ha valami a vártnál később történik, az erst szót használjuk: Er kommt erst um zehn."
      ],
