      "layout": "standardStudy",
      "translation": "magát • magának",
      "explanation": [
        "Lényeg: a sich visszaható névmás harmadik személyben és az udvarias Sie formában: azt mutatja, hogy a cselekvés magára a cselekvőre irányul. Akkusativ (tárgyeset) és Dativ (részes eset) alakja ugyanaz: sich.",
        "A többi személynek más alakja van: ich – mich, du – dich, wir – uns, ihr – euch. Például er wäscht sich (megmosakszik), de ich wasche mich.",
        "Sok német ige visszaható (sich freuen, sich setzen, sich vorstellen), magyar megfelelőjükben viszont gyakran nincs „magát” névmás: örül, leül, bemutatkozik."
      ],
