      "translation": "biztonságos • biztosan",
      "explanation": [
        "Lényeg: a sicher melléknév és határozószó is. Melléknévként jelentése biztonságos (veszélytelen: ein sicherer Weg) vagy biztos (Ich bin sicher — biztos vagyok benne). Határozószóként jelentése biztosan, persze: Er kommt sicher.",
        "A sich (Dat) sicher sein kifejezés jelentése: biztos valamiben: Ich bin mir sicher. Fokozás: sicherer, am sichersten; a főnév die Sicherheit (biztonság).",
        "A Sicher önmagában válasz is lehet: Sicher! — Persze!"
      ],
