      "explanation": [
        "Fő gondolat: a zu elöljárószó, mindig Dativot (részes eset) vonz, és személyhez vagy helyre irányuló mozgást jelöl — magyarul gyakran a -hoz/-hez/-höz rag felel meg neki: zu meiner Oma, zum Arzt, zur Schule. Otthon (hol?) = zu Hause, haza (hová?) = nach Hause.",
        "A zu célt is kifejez (zum Essen — étkezésre), jelentheti azt, hogy túl, túlságosan (zu heiß — túl forró), és a főnévi igenév előtti szócska is: Ich habe keine Lust, zu arbeiten.",
        "Összevont alakok: zu dem = zum, zu der = zur."
      ],
      "examples": [
        {
          "de": "Ich gehe zum Arzt.",
          "lv": "Orvoshoz megyek."
        },
        {
          "de": "Wir fahren zu meiner Oma.",
          "lv": "A nagymamámhoz utazunk."
        },
        {
          "de": "Er geht zu Fuß zur Schule.",
          "lv": "Gyalog megy iskolába."
        },
        {
          "de": "Der Kaffee ist zu heiß.",
          "lv": "A kávé túl forró."
        },
        {
          "de": "Sie ist zu Hause.",
          "lv": "Otthon van."
        }
      ],
      "comparison": [
        {
          "word": "nach",
          "meaning": "-ba/-be (város / ország)",
          "example": "Ich fahre nach Berlin. – Berlinbe utazom."
        },
        {
          "word": "bei",
          "meaning": "-nál/-nél (tartózkodás)",
          "example": "Ich bin beim Arzt. – Az orvosnál vagyok."
        },
        {
          "word": "in",
          "meaning": "-ba/-be (valaminek a belsejébe)",
          "example": "Ich gehe in den Supermarkt. – Bemegyek a szupermarketbe."
        }
      ],
      "tip": [
        "Jegyezd meg: zu = wohin? (irány, hová?), bei = wo? (valakinél, hol?) — akárcsak a magyar -hoz és -nál.",
        "Személyekkel a zu áll: zu mir, zu dir, zu uns (hozzám, hozzád, hozzánk)."
      ],
      "important": [
        "A zu csak Dativot vonz: zu meinem Freund, zu der Schule.",
        "Városok és országok esetén nach áll, nem zu: nach Berlin."
      ],
