        "A Guten Appetit! evés előtti jókívánság, magyarul „Jó étvágyat!”. Ha valaki egy konkrét ételre vágyik, azt mondja: Appetit auf + Akkusativ (tárgyeset): Appetit auf Eis.",
        "A der Appetit közel áll a der Hunger szóhoz, de az étvágy az evés iránti kedv, az éhség pedig testi szükséglet."
