        "Gyakori kapcsolatok: Sommerferien, Winterferien, in den Ferien (a szünidőben), Ferien haben. A diákoknak és egyetemistáknak Ferien van, a dolgozó embernek Urlaub.",
        "A névelő többes számban die, Dativ (részes eset) alakban den: in den Ferien."
